/* @socom-skeleton stub EmptyAssetRecycleBin__3zdbFv */
void zdb::EmptyAssetRecycleBin()
{
	/* 0x231a10: delete every released library waiting in the recycle bin, then empty it */
	for (CAssetList::iterator it = g_assetsRecycle.begin(); it != g_assetsRecycle.end(); ++it)
	{
		delete *it;
		*it = NULL;
	}

	g_assetsRecycle.erase(g_assetsRecycle.begin(), g_assetsRecycle.end());
	g_assetsRecycle.m_cache_model = NULL;
}

/* @socom-skeleton body __ct__Q23zdb9CAssetLibFPCc */
namespace zdb {
CAssetLib::CAssetLib(const char* name)
	{
		m_name = NULL;
		m_texture_buffer = NULL;
		m_model_buffer = NULL;
		m_iRefCount = 1;
		m_autoload = true;
		m_locked = false;
		m_gearlib = false;
		m_renderphase = _RenderPhase::WORLD;

		if (m_name)
			zfree(m_name);

		m_name = zstrdup(name);
	}
}

/* @socom-skeleton stub __dt__Q23zdb9CAssetLibFv */
zdb::CAssetLib::~CAssetLib()
{
	/* 0x231750: the models (each forgets the library first, so its destructor does not
	 * search this list), the texture and model data buffers, the texture handles, the
	 * palettes and the name */
	for (CModelVector::iterator it = m_models.begin(); it != m_models.end(); ++it)
	{
		(*it)->m_AssetLib = NULL;
		delete *it;
		*it = NULL;
	}

	m_models.clear();

	if (m_texture_buffer != NULL)
		_free(m_texture_buffer, "node_assetlib.cpp", 0x6e);

	m_texture_buffer = NULL;

	if (m_model_buffer != NULL)
		_free(m_model_buffer, "node_assetlib.cpp", 0x72);

	m_model_buffer = NULL;
	m_textures.Free();

	for (CTexPalList::iterator it = m_palettes.begin(); it != m_palettes.end(); ++it)
		delete *it;

	m_palettes.clear();

	if (m_name != NULL)
		_free(m_name, "node_assetlib.cpp", 0x7c);

	m_name = NULL;
}

/* @socom-skeleton body RootName__Q23zdb9CAssetLibFv */
char * zdb::CAssetLib::RootName()
	{
		size_t length = strlen(m_name);

		for (s32 i = length - 1; i > -1; i--)
		{
			char c = m_name[i];

			if (c == '/' || c == '\\')
			{
				return m_name + i + 1;
			}
		}

		return m_name;
	}

/* @socom-skeleton body IsNamed__Q23zdb9CAssetLibFPCc */
bool zdb::CAssetLib::IsNamed(const char *name)
	{
		bool isnamed = false;

		if (!strcmp(name, m_name))
			return true;

		size_t length = strlen(name);
		s32 i = length - 1;
		length = strlen(m_name);
		s32 j = length - 1;
		isnamed = true;

		// TODO:
		// clean this up
		do
		{
			for (; (-1 < i) && (name[i] == '/' || name[i] == '\\'); --i) {}
			for (; (-1 < j) && (m_name[j] == '/' || m_name[j] == '\\'); --j) {}

			if (i < 0 || j < 0)
			{
				if (i == j)
				{
					return isnamed;
				}

				isnamed = false;
			}
			else if (name[i] == m_name[j])
			{
				i--;
				j--;
			}
			else
			{
				isnamed = false;
			}
		} while (isnamed);

		return isnamed;
	}

/* @socom-skeleton body AddTexture__Q23zdb9CAssetLibFPCc */
namespace zdb {
bool CAssetLib::AddTexture(const char* name)
	{
		if (!name)
			return false;

		if (m_locked)
			return false;

		for (auto i = CAssetMgr::m_assets.begin(); i != CAssetMgr::m_assets.end(); i++)
		{
			CTexHandle* handle = (*i)->m_textures.GetHandle(name);

			if (handle)
			{
				AddTexture(handle->m_texture);
				return true;
			}
		}

		return false;
	}
}

/* @socom-skeleton body AddTexture__Q23zdb9CAssetLibFPQ23zdb8CTexture */
namespace zdb {
bool CAssetLib::AddTexture(CTexture* texture)
	{
		if (!texture)
			return false;

		if (m_locked)
			return false;

		for (auto i = CAssetMgr::m_assets.begin(); i != CAssetMgr::m_assets.end(); i++)
		{
			CTexHandle* handle = (*i)->m_textures.GetHandle(texture->m_name);

			if (handle)
				break;
		}

		m_textures.Append(texture, true);
		texture->m_AssetLib = this;

		return true;
	}
}

/* @socom-skeleton body AddModel__Q23zdb9CAssetLibFPQ23zdb6CModel */
namespace zdb {
CModel* CAssetLib::AddModel(CModel* model)
	{
		char* name = NULL;

		CAssetLib* library = NULL;
		CAssetLib* resolved = NULL;
		CModel* asset = NULL;

		if (m_locked)
			return NULL;

		name = model->m_name;
		asset = model;

		for (auto i = CAssetMgr::m_assets.begin(); i != CAssetMgr::m_assets.end(); i++)
		{
			CModel* mdl = (*i)->m_models.GetModel(name);

			if (mdl)
			{
				library = *i;
				break;
			}
		}

		if (!library)
		{
			m_models.insert(m_models.begin(), asset);
			asset->m_AssetLib = this;
		}

		return asset;
	}
}

/* @socom-skeleton body AddPalette__Q23zdb9CAssetLibFPQ23zdb11CTexPaletteb */
namespace zdb {
CTexPalette* CAssetLib::AddPalette(CTexPalette* palette, bool checkDuplicate)
	{
		if (checkDuplicate)
		{
			for (auto i = m_palettes.begin(); i != m_palettes.end(); ++i)
			{
				if (palette == *i)
					return NULL;
			}
		}

		m_palettes.insert(m_palettes.begin(), palette);
		palette->m_AssetLib = this;
		
		return NULL;
	}
}

/* @socom-skeleton stub Clear__Q23zdb10CAssetListFv */
void zdb::CAssetList::Clear()
{
	/* 0x230f10: delete every library in the list and empty it */
	for (iterator it = begin(); it != end(); ++it)
	{
		delete *it;
		*it = NULL;
	}

	erase(begin(), end());
	m_cache_model = NULL;
}

/* @socom-skeleton body GetTexHandle__Q23zdb10CAssetListFPCc */
namespace zdb {
CTexHandle* CAssetList::GetTexHandle(const char* name)
	{
		CTexHandle* handle = NULL;

		for (auto i = begin(); i != end(); i++)
		{
			CTexHandle* handle = (*i)->m_textures.GetHandle(name);

			if (handle)
				return handle;
		}

		return NULL;
	}
}

/* @socom-skeleton body FindLib__Q23zdb10CAssetListFPCc */
namespace zdb {
CAssetLib* CAssetList::FindLib(const char* name)
	{
		CAssetLib* lib = NULL;
		
		if (!name)
			return NULL;

		for (auto i = begin(); i != end(); i++)
		{
			if ((*i)->IsNamed(name))
			{
				lib = *i;
				break;
			}
		}

		if (lib)
			return lib;

		/* 0x230d80: else the first library whose root name (after its last '/' or '\', as
		   RootName, inline) is the name. Was: the scan never stopped at the last slash and
		   was then overwritten, so the whole path was compared ("clib" never matched
		   "//sp/m8/clib"). */
		for (auto i = begin(); i != end(); i++)
		{
			CAssetLib* alib = *i;
			char* libname = alib->m_name;

			for (s32 idx = (s32)strlen(alib->m_name) - 1; idx >= 0; idx--)
			{
				char c = alib->m_name[idx];

				if (c == '/' || c == '\\')
				{
					libname = alib->m_name + idx + 1;
					break;
				}
			}

			if (strcmp(libname, name) == 0)
				return *i;
		}

		return lib;
	}
}

/* @socom-skeleton stub FindLib__Q23zdb10CAssetListFQ23zdb12_RenderPhase */
zdb::CAssetLib * zdb::CAssetList::FindLib(zdb::_RenderPhase phase)
{
	/* 0x230c40: the first library of that render phase (byte +0x2b), else NULL */
	for (iterator it = begin(); it != end(); ++it)
	{
		if ((u8)(*it)->m_renderphase == (u8)phase)
			return *it;
	}

	return NULL;
}

/* @socom-skeleton body GetModel__Q23zdb10CAssetListFPCc */
namespace zdb {
CModel* CAssetList::GetModel(const char* name)
	{
		if (m_cache_model)
		{
			if (name && !strcmp(m_cache_model->m_name, name))
				return m_cache_model;
		}

		for (auto i = begin(); i != end(); i++)
		{
			CAssetLib* lib = *i;
			CModel* model = lib->m_models.GetModel(name);

			if (model)
				return m_cache_model = model;
		}

		return NULL;
	}
}

/* @socom-skeleton body GetLoadedLibRef__Q23zdb9CAssetMgrFPCc */
namespace zdb {
CAssetLib* CAssetMgr::GetLoadedLibRef(const char* name)
	{
		/* 0x2307a0: a loaded library gains a reference; one waiting in the recycle bin
		   gains a reference and moves back to the end of the loaded list; otherwise the
		   bin is emptied and the library is created at the end of the list and loaded.
		   The bin is emptied again before returning. Was: the port revived a recycled
		   library without taking it out of the bin, then deleted the bin's contents (the
		   revived library too), and inserted new libraries first. */
		CAssetLib* lib = m_assets.FindLib(name);

		if (lib != NULL)
		{
			lib->m_iRefCount++;
		}
		else
		{
			lib = g_assetsRecycle.FindLib(name);

			if (lib != NULL)
			{
				lib->m_iRefCount++;
				g_assetsRecycle.remove(lib);
				m_assets.insert(m_assets.end(), lib);
			}
			else
			{
				EmptyAssetRecycleBin(); /* inlined in the ELF */
				CSaveLoad sload;
				CAssetLib* assetlib = new CAssetLib(name);
				m_assets.insert(m_assets.end(), assetlib);
				lib = assetlib;
				sload.LoadAssetLib(NULL, assetlib, TYPE_ALL);
			}
		}

		EmptyAssetRecycleBin(); /* inlined in the ELF */
		return lib;
	}
}

/* @socom-skeleton stub ReleaseLibRef__Q23zdb9CAssetMgrFPQ23zdb9CAssetLib */
void zdb::CAssetMgr::ReleaseLibRef(zdb::CAssetLib *lib)
{
	/* 0x230700: the last reference moves the library from the loaded list to the end of
	 * the recycle bin (GetLoadedLibRef can take it back; EmptyAssetRecycleBin deletes it) */
	if (lib == NULL)
		return;

	lib->m_iRefCount--;

	if (lib->m_iRefCount > 0)
		return;

	m_assets.remove(lib);
	m_assets.m_cache_model = NULL;
	g_assetsRecycle.insert(g_assetsRecycle.end(), lib);
}
